    m.StateUpdateFlags = 0;
    r.SetupBackgroundStates();                               // unchanged: no dirty flag
    if (m.StateUpdateFlags != 0 || m.updates != 2) { printf("00b671a0_TEST FAIL\n"); return 1; }
